  "items:ring_master_hunting:description": "Отполировано тысячей поставленных и сработавших ловушек. Каждая добыча с поимки с шансом 5 % выпадает вдвойне.",
  "items:ring_master_completion:name": "Кольцо Завершения",
  "items:ring_master_cooking:description": "Испачкано каждым блюдом, за которым оно присматривало. Блюда, приготовленные в нём, никогда не портятся.",
  "items:ring_master_cooking:name": "Кольцо Кулинара Душ",
  "items:ring_master_defence:name": "Кольцо Оплота",
  "items:ring_master_farming:description": "Пахнет вскопанной землёй и терпеливыми временами года. Грядки созревают на 8% быстрее, пока оно надето.",
  "items:ring_master_farming:name": "Кольцо Хранителя Могил",
  "items:ring_master_fishing:description": "Едва уловимо пахнет глубинными водами и вещами постарше. 5% шанс поймать двойной улов.",
  "items:ring_master_fishing:name": "Кольцо Рыболова Пустоты",
  "items:ring_master_foraging:description": "Хранит осколок каждого листа, которого оно когда-либо касалось. 5% шанс собрать двойной урожай.",
  "items:ring_master_foraging:name": "Кольцо Дикого Собирателя",
  "items:ring_master_herblore:description": "Пропитано горькими парами дольше, чем хранит память. Тоники и зелья действуют на 10% дольше, пока оно надето.",
  "items:ring_master_herblore:name": "Кольцо Ядовара",
  "items:ring_master_jewelcrafting:description": "Ловит свет, будто тысяча неогранённых самоцветов. 5% шанс огранить двойной самоцвет.",
  "items:ring_master_jewelcrafting:name": "Кольцо Самоцветных Дел Мастера",
  "items:ring_master_leatherworking:description": "Вырезано мастером, что не тратил впустую ничего. 5% шанс, что ремесло сбережёт материалы.",
  "items:ring_master_leatherworking:name": "Кольцо Мастера-Кожевника",
  "items:ring_master_magic:name": "Кольцо Архимага",
  "items:ring_master_mining:description": "Выковано в глубочайших пластах, помнит каждую жилу, которой касалось. 5% шанс добыть двойную руду.",
  "items:ring_master_mining:name": "Кольцо Взломщика Глубин",
  "items:ring_master_power:name": "Кольцо Военачальника",
  "items:ring_master_ranged:name": "Кольцо Соколиного Глаза",
  "items:ring_master_runecrafting:description": "Едва слышно гудит связанными рунами. 5% шанс связать двойную руну.",
  "items:ring_master_runecrafting:name": "Кольцо Рунопряда",
  "items:ring_master_slayer:description": "Отмечено счётом тысячи контрактов. Приносит на 10% больше очков Slayer.",
  "items:ring_master_slayer:name": "Кольцо Мастера Наград",
  "items:ring_master_smithing:description": "Опалено тысячей горнов, но так и не расплавлено. 5% шанс, что кузня сбережёт материалы.",
  "items:ring_master_smithing:name": "Кольцо Мастера Кузни",
  "items:ring_master_thieving:description": "Ускользает сквозь пальцы, точно дым. Повышает успех кражи на 3%.",
