  "items:dimweave_hood:description": "Капюшон, плотно сотканный из нити тусклой эссенции. Тени уютно скапливаются в его складках.",
  "items:dimweave_hood:name": "Капюшон тусклого плетения",
  "items:dimweave_leggings:description": "Поножи из грубого крапивного полотна, окрашенного в сумеречно-серый, с руной сумерек, вшитой вдоль подола. Весят больше, чем кажется.",
  "items:dimweave_leggings:name": "Поножи тусклого плетения",
  "items:dimweave_robe:description": "Многослойное одеяние из тусклой эссенции, едва слышно гудящее между тканью ученика и истинной силой.",
