  "items:dimweave_sandals:description": "Мягкие сандалии, прошитые тусклой эссенцией. Шаги становятся тише, а мысли — ещё тише.",
  "items:dimweave_sandals:name": "Сандалии тусклого плетения",
  "items:dimweave_wraps:description": "Обмотки из грубого крапивного полотна, окрашенного в сумеречно-серый, с руной сумерек, вшитой в каждую ладонь. Пальцы остаются свободными для заклинаний.",
