  "quests:daily_h_smelt_adamantium_4:name": "Адамантиевые слитки",
  "quests:daily_h_smelt_mithril_5:name": "Мифриловая смена",
  "quests:daily_m_craft_iron_arrows_20:name": "Поставка железа",
  "quests:daily_m_gather_80:name": "Полный мешок",
  "quests:daily_m_kill_goblins_20:name": "Отстрел гоблинов",
  "quests:daily_m_kill_mire_crawler:name": "Очиститель топей",
  "quests:daily_m_kill_pitch_beetle:name": "Давитель жуков",
  "quests:daily_m_kill_shaman_8:name": "Заставь шамана замолчать",
  "quests:daily_m_kill_thorn_wolf:name": "Волчий дозор",
  "quests:daily_m_smelt_blacksteel_4:name": "Тёмный сплав",
  "quests:daily_m_smelt_steel_6:name": "Производство стали",
  "quests:daily_ma_craft_runite_arrows_20:name": "Поставка рунита",
  "quests:daily_ma_kill_ember_elemental_30:description": "Погаси 30 тлеющих элементалей, бушующих в Шлаковой яме.",
  "quests:daily_ma_kill_ember_elemental_30:name": "Гаситель тлеющих",
  "quests:daily_ma_kill_frost_hexer_15:description": "Заставь замолчать 15 ледяных проклинателей, пока их морозные проклятья не расползлись по яме.",
  "quests:daily_ma_kill_frost_hexer_15:name": "Ледяная тишина",
  "quests:daily_ma_kill_frost_hound_20:description": "Выследи 20 ледяных гончих, рыщущих в промёрзших глубинах Шлаковой ямы.",
  "quests:daily_ma_kill_frost_hound_20:name": "Сокрушитель стаи",
  "quests:daily_ma_kill_iron_revenant_25:description": "Изгони 25 железных ревенантов из глубочайших залов Шлаковой ямы.",
  "quests:daily_ma_kill_iron_revenant_25:name": "Охота на железных призраков",
  "quests:daily_ma_kill_slag_kobold_40:description": "Истреби 40 шлаковых кобольдов, заполонивших Шлаковую яму.",
  "quests:daily_ma_kill_slag_kobold_40:name": "Истребление кобольдов",
  "quests:daily_ma_kill_total_60:name": "Резня эпох",
  "quests:daily_ma_smelt_bloodiron_3:name": "Кровавый металл",
  "quests:daily_ma_smelt_runite_4:name": "Рунитовый тигель",
  "quests:daily_ve_cook_shrimp:name": "Завтрак в порту",
  "quests:daily_ve_craft_bronze_bar:name": "Основы бронзы",
  "quests:daily_ve_fletch_shafts:name": "Партия кожи",
  "quests:daily_ve_gather_any_10:name": "Гонец",
  "quests:daily_ve_gather_logs:name": "Утренняя поленница",
  "quests:daily_ve_kill_boar_5:name": "Кабанья докука",
  "quests:daily_ve_kill_chickens:name": "Отстрел на птичьем дворе",
  "quests:daily_ve_kill_cows:name": "Прореживание стада",
  "quests:daily_ve_kill_goblins_5:name": "Пограничный дозор",
  "quests:daily_ve_smith_copper:name": "Кузня не дремлет",
  "quests:q_ash_hunter:name": "Истребитель Пепельных полей",
  "quests:q_blackthorn_1:name": "В Терновый лес",
  "quests:q_blackthorn_2:description": "Пройди глубже в Терновый лес, к курганам под его корнями, и победи 25 корявых корневиков.",
  "quests:q_blackthorn_2:name": "Корявая глушь",
  "quests:q_boar_hunter:description": "Убей 15 диких кабанов на Пастбищах. Без изгороди и пастуха они обзавелись собственными повадками, а Тлеющему Оплоту нужны их шкуры.",
  "quests:q_boar_hunter:name": "Дикая охота",
  "quests:q_crypt_1:name": "Кости павших",
  "quests:q_crypt_2:name": "Неупокоенные мертвецы",
  "quests:q_crypt_3:name": "Ледяная тишина",
  "quests:q_dire_wolf_hunt:name": "Ужас дебрей",
  "quests:q_fighter_1:description": "Победи всего 75 врагов. Кровь и пот куют бойца, нужного Тлеющему Оплоту.",
  "quests:q_fighter_1:name": "Бывалый боец",
  "quests:q_fighter_2:description": "Срази всего 200 врагов. Слуги уже начинают запоминать твоё имя.",
  "quests:q_fighter_2:name": "Закалённый воин",
  "quests:q_fighter_3:description": "Победи всего 500 врагов. Каждый павший враг оставляет запись, которую пепел так и не получит.",
  "quests:q_fighter_3:name": "Ветеран сотни битв",
  "quests:q_first_blood:name": "Кровь гоблина",
  "quests:q_first_steps:name": "Первые шаги",
  "quests:q_frost_hound:name": "Холодная охота",
  "quests:q_gatherer:name": "Сборщик",
  "quests:q_gatherer_2:description": "Собери всего 5000 предметов для Тлеющего Оплота. Эта земля отдаёт то немногое, что у неё осталось, лишь упорным.",
  "quests:q_gatherer_2:name": "Неутомимый собиратель",
  "quests:q_goblin_slayer:description": "Оттесни гоблинскую банду ещё дальше: убей 30 гоблинов в Порубежье, некогда бывшем щитом-стеной Предела.",
  "quests:q_goblin_slayer:name": "Убийца гоблинов",
  "quests:q_miner_1:description": "Достигни 5-го уровня Горного дела и открой более богатые жилы для кузни Тлеющего Оплота.",
  "quests:q_miner_1:name": "Кирка и камень",
  "quests:q_miner_2:description": "Достигни 30-го уровня Горного дела. Более глубокие жилы Порубежья требуют более крепкой руки.",
  "quests:q_miner_2:name": "Железная воля",
  "quests:q_miner_3:description": "Достигни 50-го уровня Горного дела. Редчайшие руды Предела залегают глубоко под землёй, глубже, чем когда-либо.",
  "quests:q_miner_3:name": "Зов глубин земли",
  "quests:q_moss_golem_hunt:name": "Моховая напасть",
  "quests:q_roc_fledgling:name": "Небесный дозор Нагорья",
  "quests:q_shaman_hunt:description": "Гоблины-шаманы тянут Тусклую эссенцию из старых сторожевых костров и подталкивают банду к войне. Заставь замолчать 10 из них.",
  "quests:q_shaman_hunt:name": "Охота на шаманов",
  "quests:q_skiller_1:name": "Мастер на все руки",
  "quests:q_skiller_2:name": "Разносторонний искатель",
  "quests:q_skiller_3:name": "Бывалый искатель",
  "quests:q_skiller_4:name": "Путь мастерства",
  "quests:q_skiller_5:name": "Легенда Очага",
  "quests:q_slagpit_1:name": "В Яму",
  "quests:q_slagpit_2:name": "Железное наваждение",
  "quests:q_smith_journeyman:description": "Достигни 20-го уровня Кузнечного дела. Кузня Тлеющего Оплота вознаграждает терпение: освой основы, прежде чем браться за твёрдые металлы.",
  "quests:q_smith_journeyman:name": "Кузнец-подмастерье",
  "quests:q_smith_master:name": "Мастер кузни",
  "quests:q_stag_hunter:name": "Король леса",
