  // ── 1.2.0 "Fasern und Fallen": Fasern, Stoff und Jagen (content-dev, 27.08.2026) ──────────
  "skills:hunting:name": "Охота",
  "categories:forage_fibers:name": "Волокна",
  "categories:weave:name": "Ткачество",

  "items:fiber_nettle:name": "Крапивное волокно",
  "items:fiber_nettle:description": "Стебли жгучей крапивы, очищенные и высушенные, пока жжение не исчезнет и не останется только нить.",
  "items:fiber_flax:name": "Лён",
  "items:fiber_flax:description": "Тонкие стебли, вымоченные и расчёсанные до гладкости, — древнейшая нить, что когда-либо пряли в Рубеже.",
  "items:fiber_thornhemp:name": "Колючая конопля",
  "items:fiber_thornhemp:description": "Грубое волокно из живой изгороди, которая не сдаётся без боя, довольно крепкое, чтобы притупить лезвие.",
  "items:fiber_ghostsilk:name": "Призрачный шёлк",
  "items:fiber_ghostsilk:description": "Бледные нити, спрядённые чем-то, что живёт там, где кончается свет.",
  "items:fiber_starflax:name": "Звёздный лён",
  "items:fiber_starflax:description": "Волокно со слабым холодным мерцанием, будто оно помнит небо, под которым выросло.",
  "items:nettle_seed:name": "Семя крапивы",
  "items:nettle_seed:description": "Крохотное чёрное семя, посади его и побереги руки к сбору урожая.",
  "items:flax_seed:name": "Семя льна",
  "items:flax_seed:description": "Маленькое маслянистое семя, из которого вырастает древнейшая ткань Рубежа.",
  "items:thornhemp_seed:name": "Семя колючей конопли",
  "items:thornhemp_seed:description": "Твёрдое семя живой изгороди, которая скорее укусит, чем зацветёт.",
  "items:ghostsilk_seed:name": "Семя призрачного шёлка",
  "items:ghostsilk_seed:description": "Семя, бледное как кость, — говорят, лучше всего прорастает там, где больше ничего не растёт.",
  "items:starflax_seed:name": "Семя звёздного льна",
  "items:starflax_seed:description": "Семя, слабо мерцающее в сумерках, достаточно терпеливое, чтобы пролежать под землёй целый сезон.",
  "items:cloth_nettle:name": "Крапивная ткань",
  "items:cloth_nettle:description": "Грубо сотканная ткань из самого скромного волокна Рубежа, достаточно тёплая для первой робы.",
  "items:cloth_linen:name": "Полотно",
  "items:cloth_linen:description": "Гладкое, ровно сотканное полотно — рабочая ткань любого портновского стола.",
  "items:cloth_thornlinen:name": "Колючее полотно",
  "items:cloth_thornlinen:description": "Полотно, туго сотканное с нитью колючей конопли, достаточно жёсткое, чтобы смягчить лёгкий удар.",
  "items:cloth_ghostweave:name": "Призрачная ткань",
  "items:cloth_ghostweave:description": "Ткань, сотканная из призрачного шёлка, бледная и прохладная, — говорят, глушит даже стук сердца заклинателя.",
  "items:cloth_starweave:name": "Звёздная ткань",
  "items:cloth_starweave:description": "Звёздный лён, сотканный в ткань, что хранит слабый холодный свет ещё долго после того, как станок замолкает.",
  "items:bait_worm:name": "Наживка-червь",
  "items:bait_maggot:name": "Наживка из опарышей",
  "items:bait_crab:name": "Наживка из краба",
  "items:bait_squid:name": "Наживка из кальмара",
  "items:bait_glow:name": "Светящаяся наживка",
  "items:bait_worm:description": "Толстый извивающийся червь, свежевыкопанный на берегу реки, годится и для крючка, и для ловушки.",

  "actions:forage_nettle:name": "Собрать крапиву",
