  "items:oreveined_hoop:name": "Кольцо Рудной Жилы",
  "items:oreveined_hoop:description": "Инкрустировано осколком сапфира поверх необработанной руды, ещё слабо пахнущей жилой, из которой её добыли. Изредка удваивает добычу от удара.",
  "items:thriftcut_cinch:name": "Кольцо Бережливого Кроя",
  "items:thriftcut_cinch:description": "Алмаз в оправе из мифрила, отполированный руками, что никогда не тратили впустую ни один срез шкуры.",
  "items:steadhand_cuff:name": "Кольцо Твёрдой Руки",
  "items:steadhand_cuff:description": "Оникс, скреплённый проволокой, тронутой пустотой. Не даёт руке дрогнуть в тот единственный момент, когда это важнее всего.",
  "items:harvestward_clutch:name": "Цепь Стража Урожая",
  "items:harvestward_clutch:description": "Цепь из пустотного камня, обёрнутая звёздной тканью, тёплая, как вспаханная земля, даже в разгар зимы.",
  "sets:hunters_accord_set:name": "Уговор Охотника (2 предмета)",
