  "monsters:dg_wreath_bearer:name": "Носитель венка",
  "monsters:dg_prayer_eater:name": "Пожиратель молитв",
  "dungeons:expunged_chapel:name": "Стёртая часовня",
  "dungeons:expunged_chapel:waveMeta.0.name": "Процессия",
  "dungeons:expunged_chapel:waveMeta.1.name": "Пробел",
  "dungeons:expunged_chapel:waveMeta.2.name": "Стиратель",
  "quests:chronicle_22:name": "Пустой зал",
  "quests:chronicle_23:name": "Освящение",
  "quests:chronicle_24:name": "Что пили идолы",
  "quests:chronicle_25:name": "Венки",
  "quests:chronicle_25:loreText": "Я видел, как их отливали в Шлаковой яме, тогда, когда я ещё верил, что предостерегать — это ремесло. Первые венки из божественного железа, направляемые руками, что не были человеческими. И вот они снова здесь. Носители венка идут процессией по длинному залу, плечом к плечу, неся то, что на них возложили, словно процессия ещё не закончилась. Никто не сказал им, куда они идут. Это никогда и не было решено. Ты встал у них на пути, и они пали, как падают творения: без жалоб, с большим шумом. Я разглядывал литейные швы на осколках, пока рука не успокоилась. Швы снимают, когда творение закончено. Эти так и не были закончены. Это облегчает мне душу так, что объяснять я не стану.",
  "quests:chronicle_26:name": "Осадные творения",
  "quests:chronicle_26:loreText": "Идолы были его осадными машинами против неба. Я записал эту фразу, когда Дражан её произнёс, и лишь сегодня понял, что он говорил буквально. В конце Зала они стоят в ряд, склонившись к небу, руки перелиты в метательные рычаги, незаконченные и без хозяина. То, во что они должны были бить, хранит молчание. Я бы предпочёл, чтобы никто их не достроил. Ты валил их одного за другим, и когда лёг последний, стена за ними открылась. Дверь, которой нет ни на одном плане Зала, а планы у меня есть. За ней крыло, где каждая надпись выщерблена, чисто, строка за строкой. Здесь кто-то работал. Не думаю, что он закончил.",
  "quests:chronicle_27:name": "Стиратель",
  "quests:chronicle_27:description": "Очисти Стёртую часовню и срази Стирателя: то, что вырезало Писания, всё ещё за работой.",
  "quests:chronicle_27:loreText": "Процессия у входа, пробел за ней, а в конце часовни он. Он не поднял глаз, когда ты пришёл. Он орудовал резцом. Стиратель есть рука, вырезавшая имя Седьмого из Писаний, и она не перестала резать, потому что имя может вернуться, если ему позволить. Ты сразил его, и его работа осталась как была: стены, полные пробелов, и все одной формы. Я провёл по одному рукой. Он совпадает с пробелом, в который молятся жрецы. Пишу это сухо, потому что иначе не умею: Седьмого не забыли. Его держат в забвении. Кто этого хочет, нет ни в одной моей книге — пока нет. Войны Богов начинаются не с богов. Они начинаются с того, что кто-то хотел стереть.",
  "achievements:ach_chapter_22:name": "Пустой зал",
  "achievements:ach_chapter_22:description": "Заверши главу 22 Хроники: Пустой зал.",
  "achievements:ach_chapter_23:name": "Освящение",
  "achievements:ach_chapter_23:description": "Заверши главу 23 Хроники: Освящение.",
  "achievements:ach_chapter_24:name": "Что пили идолы",
  "achievements:ach_chapter_24:description": "Заверши главу 24 Хроники: Что пили идолы.",
  "achievements:ach_chapter_25:name": "Венки",
  "achievements:ach_chapter_25:description": "Заверши главу 25 Хроники: Венки.",
  "achievements:ach_chapter_26:name": "Осадные творения",
  "achievements:ach_chapter_26:description": "Заверши главу 26 Хроники: Осадные творения.",
  "achievements:ach_chapter_27:name": "Удержанный в забвении",
