  // codex:2026-10-17T15:50:00+02:00 — 1.3.0 E5/E6: Waffen ab 95, Hölzer/Fische/Gerichte/Angeln 82–99 samt Aktionen (design/1.3.0-balance-e5-e6.md).
  "items:censerwood_shortbow:name": "Короткий лук из ладанного дерева",
