  // claude:2026-10-30T18:46:25+01:00 — 1.4.2: Jägerkodex-Erzählsätze (talentNodes:<baum>.<knoten>:flavor).
  "talentNodes:slayer.tracking:flavor": "Бренна читает след, как другие читают письмо.",
  "talentNodes:slayer.trail:flavor": "Невезение рано или поздно кончается. Терпение никогда.",
  "talentNodes:slayer.collar:flavor": "Ещё один ошейник на крюке у двери.",
  "talentNodes:slayer.pace:flavor": "Бренна платит за каждую голову и считает быстро.",
  "talentNodes:slayer.spoils:flavor": "Зверь, за которым тебя посылают, всегда несёт при себе что-то, ради чего стоило идти.",
  "talentNodes:slayer.lore:flavor": "Кто убил каждый вид хоть раз, знает, где ломается каждый из них.",
  // claude:2026-10-18T12:00:00+02:00 — Narbenbuch (Prestige „Der Aschesturz“, Welle B2): Baum, Äste, Knoten.
  "talentTrees:prestige:name": "Книга шрамов",
  "talentTrees:prestige:description": "Летопись Стража о каждом Пеплопаде. Шрамы, полученные у Алтаря осколков, становятся здесь постоянными дарами для каждого следующего прохождения.",
  "talentBranches:prestige.legacy:name": "Что остаётся",
  "talentBranches:prestige.haste:name": "Короткий путь",
  "talentBranches:prestige.might:name": "Отмеченный",
