  "talentNodes:prestige.damage:name": "Кулак в шрамах",
  "talentNodes:prestige.damage:description": "Ты наносишь на {value} больше урона.", // claude:2026-10-30T18:46:25+01:00 — 1.4.2 nur Wirkung, Erzählsatz in :flavor
  "talentNodes:prestige.goldFind:name": "Сорочий глаз",
  "talentNodes:prestige.pointsBoost:name": "Глубокий надрез",
  "talentNodes:prestige.pointsBoost:description": "Каждый следующий Пеплопад приносит на {value} больше шрамов за само прохождение, а не за твою коллекцию.", // claude:2026-10-30T18:46:25+01:00 — 1.4.2 nur Wirkung, Erzählsatz in :flavor
  // claude:2026-10-30T18:46:25+01:00 — 1.4.2 Narbenbuch (Aschesturz 2.0): Erzählsätze aller Knoten, zwölf neue Knoten mit Name und Wirkung.
  "talentNodes:prestige.startingGold:flavor": "Мёртвым дают монеты в дорогу. Ты не мёртв, но монеты не помешают.",
  "talentNodes:prestige.keepTools:flavor": "Руки не забывают свой инструмент.",
  "talentNodes:prestige.keepPurchases:name": "Оплаченные счета",
  "talentNodes:prestige.keepPurchases:description": "Твой уровень авто-еды, открытое авто-усиление и все купленные ячейки банка переживают Пеплопад.",
  "talentNodes:prestige.keepPurchases:flavor": "Что оплачено, то оплачено. Даже пепел ведёт счета.",
  "talentNodes:prestige.keepBankStacks:flavor": "Что было зарыто, огня не видело.",
  "talentNodes:prestige.keepSlayerPoints:name": "Непрерванный след",
  "talentNodes:prestige.keepSlayerPoints:description": "{value} твоих очков Slayer и жетонов переживают Пеплопад.",
  "talentNodes:prestige.keepSlayerPoints:flavor": "След не остывает только потому, что охотник пал.",
  "talentNodes:prestige.keepEquipment:flavor": "Вещь, которую пепел не получит.",
  "talentNodes:prestige.earlyXp:flavor": "Что однажды выучил, во второй раз учишь быстрее.",
  "talentNodes:prestige.chronicleRecall:flavor": "Хроника не станет читать тебе главу, которую ты уже прожил.",
  "talentNodes:prestige.dungeonRecall:flavor": "Врата, которые ты однажды зачистил, тебя знают.",
  "talentNodes:prestige.masteredXp:flavor": "Руки всё ещё знают, куда тянуться.",
  "talentNodes:prestige.actionSpeed:name": "Набитая рука",
  "talentNodes:prestige.actionSpeed:description": "Действия добычи, изготовления и воровства занимают на {value} меньше времени.",
  "talentNodes:prestige.actionSpeed:flavor": "Во второй раз никому не нужно показывать тебе, как это держать.",
  "talentNodes:prestige.masteryXp:name": "Угли мастерства",
  "talentNodes:prestige.masteryXp:description": "На {value} больше опыта мастерства.",
  "talentNodes:prestige.masteryXp:flavor": "Мастерство не сгорело вместе с остальным. Оно лишь ждало новых дров.",
  "talentNodes:prestige.damage:flavor": "Костяшки, которые однажды уже ломались, больше не ломаются.",
  "talentNodes:prestige.maxHp:flavor": "Рубцовая ткань рвётся не так легко.",
  "talentNodes:prestige.goldFind:flavor": "Ты собираешь то, что принадлежало идолам, как сороки собирают серебро.",
  "talentNodes:prestige.foodHeal:name": "Тлеющая кровь",
  "talentNodes:prestige.foodHeal:description": "Еда лечит тебя на {value} сильнее.",
  "talentNodes:prestige.foodHeal:flavor": "Кровь, что уже текла сквозь пепел, принимает любое тепло, какое ей дают.",
  "talentNodes:prestige.rareDrop:name": "Зоркий глаз",
  "talentNodes:prestige.rareDrop:description": "Редкая боевая добыча (1/500 и реже) выпадает на {value} вероятнее.",
  "talentNodes:prestige.rareDrop:flavor": "Ты уже видел этот блеск. Теперь ты знаешь, куда смотреть.",
  "talentNodes:prestige.offlineHours:name": "Долгая ночь",
  "talentNodes:prestige.offlineHours:description": "Твоё офлайн-время увеличивается на {value} ч.",
  "talentNodes:prestige.offlineHours:flavor": "Огонь прогорает, но не гаснет. Работа идёт, пока тебя нет.",
  "talentNodes:prestige.workOrders:name": "Воронья почта",
  "talentNodes:prestige.workOrders:description": "Заказы приходят на {value} чаще.",
  "talentNodes:prestige.workOrders:flavor": "Вороны выучили твоё имя. С тех пор они не дают тебе покоя.",
  "talentNodes:prestige.huntTraps:name": "Зверолов",
  "talentNodes:prestige.huntTraps:description": "Число мест для ловушек на охоте растёт на {value}.",
  "talentNodes:prestige.huntTraps:flavor": "Каждая петля, что ты когда-либо ставил, всё ещё где-то у тебя в руках.",
  "talentNodes:prestige.farmPlots:name": "Семенной амбар",
  "talentNodes:prestige.farmPlots:description": "Число доступных тебе грядок растёт на {value}.",
  "talentNodes:prestige.farmPlots:flavor": "Несколько семян пережили весь пожар сухими.",
  "talentNodes:prestige.campBuild:name": "Зодчий",
  "talentNodes:prestige.campBuild:description": "Строительство в New Haven занимает на {value} меньше времени.",
  "talentNodes:prestige.campBuild:flavor": "Для того, кто однажды уже всё потерял, строители работают быстрее.",
  "talentNodes:prestige.pointsBoost:flavor": "Следующее падение режет глубже и оставляет больше.",
  "talentNodes:prestige.petEcho:name": "Эхо спутников",
  "talentNodes:prestige.petEcho:description": "Неэкипированные спутники дают {value} своего навыкового эффекта вместо 25%.",
  "talentNodes:prestige.petEcho:flavor": "Они больше не идут рядом, но всё ещё следуют за тобой.",
