  "achievements:ach_dungeon_wildwood_hunt_1:description": "Зачисти Охоту Дикого леса один раз.",
  "achievements:ach_dungeon_wildwood_hunt_10:name": "Мастер-охотник: ветеран",
  "achievements:ach_dungeon_wildwood_hunt_50:name": "Мастер-охотник: легенда",
  "achievements:ach_dungeon_highland_aerie_1:name": "Покоритель гнездовья: первая зачистка",
  "achievements:ach_dungeon_highland_aerie_1:description": "Зачисти Горное гнездовье один раз.",
  "achievements:ach_dungeon_highland_aerie_10:name": "Покоритель гнездовья: ветеран",
