  "achievements:ach_raid_gk_felmagus_normal:name": "Верховный скверномаг Зил'гат: Победа (Обычный)",
  "achievements:ach_raid_gk_felmagus_normal:description": "Победите босса в Залах Гобкха'раза: Верховный скверномаг Зил'гат. Сложность: Обычный.",
  "achievements:ach_raid_gk_felmagus_heroic:name": "Верховный скверномаг Зил'гат: Победа (Героический)",
  "achievements:ach_raid_gk_felmagus_heroic:description": "Победите босса в Залах Гобкха'раза: Верховный скверномаг Зил'гат. Сложность: Героический.",
  "achievements:ach_raid_gk_felmagus_mythic:name": "Верховный скверномаг Зил'гат: Победа (Мифический)",
  "achievements:ach_raid_gk_felmagus_mythic:description": "Победите босса в Залах Гобкха'раза: Верховный скверномаг Зил'гат. Сложность: Мифический.",
