  "achievements:ach_raid_gk_warking_heroic:description": "Победите босса в Залах Гобкха'раза: Военный король Раккзул Наследник. Сложность: Героический.",
  "achievements:ach_raid_gk_warking_mythic:name": "Военный король Раккзул Наследник: Победа (Мифический)",
